import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                comp=[(i,j)]; seen[i][j]=True; q=[(i,j)]
                while q:
                    y,x=q.pop()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; comp.append((ny,nx)); q.append((ny,nx))
                cells=set(comp); order=[]
                while cells:
                    ring={c for c in cells if any((c[0]+dy,c[1]+dx) not in cells for dy,dx in((1,0),(-1,0),(0,1),(0,-1)))}
                    col=g[ring.pop()[0]][ring.pop()[1]] if False else None
                    col=g[next(iter(ring))[0]][next(iter(ring))[1]]
                    assert all(g[y][x]==col for y,x in ring), (col,ring)
                    order.append(col); cells-=ring
                mp=dict(zip(order,order[::-1]))
                for y,x in comp: out[y][x]=mp[g[y][x]]
    return out

